import json
import re

from sqlalchemy import select, func
from sqlalchemy.orm import Session

from app.repositories.db_models import FinancialReport, CompanyAlias

_METRIC_ALIASES = {
    "property plant and equipment net": (
        "property plant equipment net",
        "property and equipment net",
        "固定资产净额",
    ),
    "cash generated by operating activities": (
        "cash generated from operating activities",
        "net cash provided by operating activities",
        "net cash from operating activities",
        "经营活动现金流",
        "经营活动产生的现金",
    ),
    "long-term debt": (
        "长期债务",
    ),
}

# 单位、期间和表格范围说明独立保留，不与普通正文片段竞争名额。
_TABLE_CONTEXT_PATTERN = re.compile(
    r"\b(?:in\s+(?:millions?|thousands?|billions?)|"
    r"years?\s+ended|as\s+of|following\s+table)\b",
    re.IGNORECASE,
)
_STOP_WORDS = frozenset(
    {
        "and",
        "from",
        "how",
        "the",
        "this",
        "was",
        "what",
        "when",
        "where",
        "which",
        "with",
    }
)

def normalize_company(value: str) -> str:
    """统一大小写、空格及标点，保留中文字符。"""
    return re.sub(r"[\W_]+", "", value.casefold())

def expand_financial_query(query: str) -> str:
    """把受控中文指标名称转换成英文检索词。"""
    for canonical, aliases in _METRIC_ALIASES.items():
        for alias in aliases:
            if re.search(r"[\u4e00-\u9fff]", alias):
                query = query.replace(alias, canonical)
    return query


def normalize_metric_label(value: str) -> str:
    """忽略大小写、标点和多余空格，保留指标名称中的有效词。"""
    return " ".join(
        re.findall(r"[a-z0-9]+|[\u4e00-\u9fff]+", value.lower())
    )


def canonical_metric_label(value: str) -> str:
    """将受控别名转换成标准名称；未知指标保留归一化后的原名。"""
    normalized = normalize_metric_label(value)
    for canonical, aliases in _METRIC_ALIASES.items():
        for candidate in (canonical, *aliases):
            if normalized == normalize_metric_label(candidate):
                return normalize_metric_label(canonical)
    return normalized


def metric_row_indexes(metrics: list[str], table: list) -> dict[str, list[int]]:
    """按完整指标名称或受控别名匹配表格第一列，返回匹配行号。"""
    matches = {}
    for metric in metrics:
        expected_label = canonical_metric_label(metric)
        indexes = []
        for index, row in enumerate(table):
            if not isinstance(row, list) or not row:
                continue
            actual_label = canonical_metric_label(str(row[0]))
            # 不用单个 debt/cash 词就断言命中，避免不同会计科目被混淆。
            if expected_label and expected_label == actual_label:
                indexes.append(index)
        matches[metric] = indexes
    return matches

def search_terms(query: str) -> list[str]:
    """提取简单英文关键词，保持当前打分规则，不引入新的语义匹配。"""
    return [
        token
        for token in re.findall(r"[a-z0-9]+", query.lower())
        if len(token) > 2 and token not in _STOP_WORDS
    ]

def company_alias_matches(alias: str, query: str) -> bool:
    """中文名称做包含匹配；英文名称/代码使用词边界，避免短代码误命中。"""
    if re.search(r"[\u4e00-\u9fff]", alias):
        matched = alias in query
    else:
        matched = bool(
            re.search(
                r"(?<![a-z0-9])" + re.escape(alias) + r"(?![a-z0-9])",
                query.casefold(),
            )
        )
    return matched or normalize_company(query) == alias


def extract_years(query: str) -> list[str]:
    """保留原有年份识别及出现顺序，供旧关键词入口自动路由。"""
    return re.findall(r"\b(?:19|20)\d{2}\b", query)

class FinQARepository:
    """ ORM相关操作（查询） """

    def __init__(self, db: Session):
        self.db = db


    def get_report(self, report_id: str, split: str | None = None) -> FinancialReport | None:
        """按原始 report_id 精确读取报告；split 可消除跨数据集歧义。"""
        statement = select(FinancialReport).where(
            FinancialReport.source_id == report_id,
        )
        if split is not None:
            statement = statement.where(FinancialReport.split == split)
        return self.db.scalars(statement.order_by(FinancialReport.split).limit(1)).first()

    @classmethod
    def compact_report(
        cls,
        report: FinancialReport,
        *,
        query: str,
        queries: list[str] | None = None,
        score: int | None = None,
        max_snippets: int = 4,
        max_table_rows: int = 6,
    ) -> dict:
        """保留指标行、表头及期间单位说明，返回当前报告的有限证据。"""
        requested_metrics = list(dict.fromkeys(
            item.strip() for item in (queries or []) if item.strip()
        ))

        # 完整保留单元格，避免字符截断破坏金额、标签和单位。
        table = [
            [str(cell) for cell in row]
            for row in report.table
            if isinstance(row, list)
        ]
        matches = metric_row_indexes(requested_metrics, table)
        matched_metrics = [
            metric for metric, indexes in matches.items() if indexes
        ]
        unmatched_metrics = [
            metric for metric, indexes in matches.items() if not indexes
        ]

        # 请求指标命中的全部行必须保留，不能被普通相关行挤掉。
        selected_indexes = {
            index for indexes in matches.values() for index in indexes
        }
        if table:
            selected_indexes.add(0)

        terms = set(search_terms(expand_financial_query(
            " ".join([query, *requested_metrics])
        )))
        ranked_rows = sorted(
            (
                (
                    sum(" ".join(row).lower().count(term) for term in terms),
                    index,
                )
                for index, row in enumerate(table)
            ),
            key=lambda item: (-item[0], item[1]),
        )
        row_limit = max(max_table_rows, len(selected_indexes - {0}))
        for relevance, index in ranked_rows:
            if len(selected_indexes - {0}) >= row_limit:
                break
            if relevance > 0:
                selected_indexes.add(index)

        # 没有目标行时保留少量原表，未匹配状态仍然明确返回。
        if selected_indexes == {0}:
            selected_indexes.update(
                range(1, min(len(table), max_table_rows + 1))
            )
        selected_rows = [table[index] for index in sorted(selected_indexes)]

        texts = list(dict.fromkeys(
            str(text).strip()
            for text in report.pre_text + report.post_text
            if str(text).strip()
        ))
        context_snippets = [
            text for text in texts if _TABLE_CONTEXT_PATTERN.search(text)
        ]
        ranked_texts = sorted(
            (
                (
                    sum(text.lower().count(term) for term in terms),
                    index,
                    text,
                )
                for index, text in enumerate(texts)
                if text not in context_snippets
            ),
            key=lambda item: (-item[0], item[1]),
        )
        text_snippets = [
            text for relevance, _, text in ranked_texts if relevance > 0
        ][:max_snippets]
        if not text_snippets:
            text_snippets = [text for _, _, text in ranked_texts[:2]]

        # 行标签匹配不是财务正确性结论，范围仅限当前报告。
        result = {
            "report_id": report.source_id,
            "split": report.split,
            "requested_metrics": requested_metrics,
            "metrics_checked": bool(requested_metrics),
            "matched_metrics": matched_metrics,
            "unmatched_metrics": unmatched_metrics,
            "matched_metric_count": len(matched_metrics),
            "metric_match_scope": "current_report_table_row_labels",
            "context_snippets": context_snippets,
            "text_snippets": text_snippets,
            "table_rows": selected_rows,
        }
        if score is not None:
            result["score"] = score
        return result

    def search(
            self,  # 仓储实例，持有数据库 Session
            query: str,  # 用户查询字符串
            report_id: str | None = None,  # 可选：精确限定某份报告
            split: str | None = None,  # 可选：限定 train / test 等数据划分
            limit: int = 5,  # 返回报告数量上限
    ) -> list[dict]:  # 返回紧凑报告字典列表
        """在有限候选报告中按关键词出现次数排序，返回紧凑而非完整报告。"""  # 文档字符串
        tokens = search_terms(query)  # 对查询分词，得到关键词列表
        statement = select(FinancialReport)  # 构造基础查询：选择 FinancialReport
        if report_id:  # 如果指定了 report_id
            statement = statement.where(FinancialReport.source_id == report_id)  # 增加 source_id 精确过滤
        if split:  # 如果指定了 split
            statement = statement.where(FinancialReport.split == split)  # 增加 split 过滤
        # SQLite 内存搜索最多扫描 200 份候选，防止模糊问题造成大表全量拼接。
        reports = list(self.db.scalars(statement.limit(200)))  # 执行查询，最多取 200 条报告对象

        scored: list[tuple[int, FinancialReport]] = []  # 存放 (相关性分数, 报告对象) 的列表
        for report in reports:  # 遍历候选报告
            table_text = " ".join(" | ".join(row) for row in report.table)  # 把表格拼成文本：行内用 |，行间用空格
            text = " ".join(  # 拼接用于打分的全文
                [report.source_id, *report.pre_text, *report.post_text, table_text]
            ).lower()  # 统一转小写，便于大小写不敏感匹配
            score = sum(text.count(token) for token in tokens)  # 统计每个关键词出现次数并求和
            if score or report_id:  # 有命中，或指定了 report_id，则保留
                scored.append((score, report))  # 加入候选
        scored.sort(key=lambda item: (-item[0], item[1].id))  # 按分数降序、id 升序排序

        return [  # 返回紧凑报告列表
            self.compact_report(report, query=query, score=score)  # 对每个报告调用 compact_report
            for score, report in scored[:limit]  # 只取前 limit 个
        ]

    def find_reports(
            self,  # 仓储实例，持有数据库 Session
            company: str,  # 公司名称或代码
            year: int | None = None,  # 可选：报告年份
            metrics: list[str] | None = None,  # 可选：指标列表
            query: str = "",  # 查询字符串
            split: str | None = None,  # 可选：数据划分
            limit: int = 5,  # 返回结果数量上限
    ) -> dict:  # 返回字典结果
        """解析公司、筛选年份、排序并返回证据；复用注入的 Session，不自行开连接。"""  # 文档字符串
        tickers = list(  # 查询公司别名对应的 ticker 列表
            self.db.scalars(
                select(CompanyAlias.ticker).where(CompanyAlias.alias == normalize_company(company))
            )
        )
        if len(tickers) != 1:  # 如果 ticker 数量不是 1
            return {  # 返回错误结果
                "found": False,  # 未找到
                "error": "company_ambiguous" if tickers else "company_unknown",  # 歧义或未知
                "candidates": tickers,  # 候选 ticker
                "hint": "请确认公司代码；目录尚未覆盖所有公司全称。",  # 提示
            }
        ticker = tickers[0]  # 取出唯一 ticker
        # 先筛选公司，不再任取全库前 200 条；保留所有年份用于澄清。
        statement = select(FinancialReport).where(  # 构造查询
            FinancialReport.source_id.startswith(ticker + "/", autoescape=True)  # source_id 以 ticker/ 开头
        )
        if split:  # 如果指定 split
            statement = statement.where(FinancialReport.split == split)  # 增加 split 过滤
        reports = list(self.db.scalars(statement))  # 执行查询，得到该公司所有报告
        years = sorted({int(r.source_id.split("/")[1]) for r in reports})  # 从 source_id 中提取年份并排序
        if year is None:  # 如果未指定年份
            return {  # 返回需要年份的结果
                "found": False,  # 未找到
                "error": "year_required",  # 错误类型：需要年份
                "ticker": ticker,  # ticker
                "available_years": years,  # 可用年份
                "hint": "请确认报告年份。",  # 提示
            }
        reports = [r for r in reports if r.source_id.split("/")[1] == str(year)]  # 过滤出指定年份的报告
        requested_metrics = list(dict.fromkeys(
            item.strip() for item in (metrics or []) if item.strip()
        ))
        expanded = expand_financial_query(" ".join([query, *requested_metrics]))
        # 年份已用于候选筛选，不再让它的正文出现次数主导排序。
        terms = {
            term for term in search_terms(expanded)
            if not re.fullmatch(r"(?:19|20)\d{2}", term)
        }
        ranked = []
        for report in reports:
            matches = metric_row_indexes(requested_metrics, report.table)
            matched_count = sum(bool(indexes) for indexes in matches.values())
            content = " ".join([
                *report.pre_text,
                *report.post_text,
                *[
                    " ".join(map(str, row))
                    for row in report.table if isinstance(row, list)
                ],
            ]).lower()
            keyword_score = sum(content.count(term) for term in terms)
            ranked.append((matched_count, keyword_score, report))

        ranked.sort(key=lambda item: (
            -item[0], -item[1], item[2].source_id, item[2].split,
        ))

        grouped = {}
        for _, keyword_score, report in ranked:
            # 正文和表格完全相同才合并；保留所有来源，不删除数据库记录。
            content_key = json.dumps(
                [report.pre_text, report.post_text, report.table],
                ensure_ascii=False,
            )
            if content_key not in grouped:
                evidence = self.compact_report(
                    report,
                    query=expanded,
                    queries=requested_metrics,
                    score=keyword_score,
                    max_table_rows=20,
                )
                evidence["source_refs"] = []
                grouped[content_key] = evidence
            grouped[content_key]["source_refs"].append({
                "report_id": report.source_id,
                "split": report.split,
            })

        results = list(grouped.values())[:max(1, min(limit, 10))]
        return {
            "found": bool(results),
            "ticker": ticker,
            "report_year": year,
            "available_years": years,
            "total_candidates": len(reports),
            "distinct_candidates": len(grouped),
            "results": results,
            "hint": (
                "结果按当前报告的指标行匹配数量优先排序。"
                "matched_metrics 表示匹配到了指标行，仍需检查年份、数值和单位。"
                "unmatched_metrics 仅表示当前报告未匹配，不能据此断言全库缺失。"
                "同内容记录的全部来源保存在 source_refs 中。"
            ),
        }

    def search_reports(
            self,
            query: str,
            split: str | None = None,
            limit: int = 3,
    ) -> list[dict]:
        """通过查询文本定位候选，不承担按报告 ID 精确读取的职责。"""

        matches = set()

        # 从查询文本中识别公司名称、别名或代码。
        for alias, ticker in self.db.execute(
                select(CompanyAlias.alias, CompanyAlias.ticker)
        ):
            if company_alias_matches(alias, query):
                matches.add(ticker)

        years = extract_years(query)

        # 公司唯一且包含年份时，使用公司年份定位流程。
        if len(matches) == 1 and years:
            located = self.find_reports(
                company=next(iter(matches)),
                year=int(years[0]),
                query=query,
                split=split,
                limit=min(limit, 3),
            )
            return located.get("results", [])

        # 无法可靠识别公司年份时，使用已有关键词搜索。
        return self.search(
            query=query,
            split=split,
            limit=min(limit, 3),
        )

    def counts(self) -> dict[str, int]:  # 返回统计字典
        """返回健康检查和运维页面使用的报告总数。"""  # 文档字符串
        return {  # 返回字典
            "reports": self.db.scalar(select(func.count()).select_from(FinancialReport)) or 0,  # 报告总数
        }
